RATE_HZ = 750.0                           # policy / solver steps per sim second
DT = 1.0 / RATE_HZ
np.set_printoptions(precision=3, suppress=True, linewidth=140)


# ---------------------------------------------------------------- the run
def run_trajectory(policy, seed_mode, hold):
    """Step the policy and filter its commands; returns t, cmd, {'on','off'} outputs."""
    arm = policy.arm
    other = SOLVER_DEFAULT_Q
    filters = {"on": SafetyFilter(collision_avoidance=True),
               "off": SafetyFilter(collision_avoidance=False)}    # OFF = control only
    n = int(round((policy.duration + hold) * RATE_HZ)) + 1
    t = np.arange(n) * DT
    cmd = np.zeros((n, 7))
    out = {k: np.zeros((n, 7)) for k in filters}
    prev = {k: policy.start.copy() for k in filters}
    for k in range(n):
        q = policy(None, t[k])[policy.indices]
        cmd[k] = q
        left, right = (q, other) if arm == "left" else (other, q)
        for key, f in filters.items():
            cur = q if seed_mode == "command" else prev[key]
            cl, cr = (cur, other) if arm == "left" else (other, cur)
            ql, qr = f.filter(left, right, q_current_left=cl, q_current_right=cr,
                              reset=(k == 0))
            out[key][k] = ql if arm == "left" else qr
            prev[key] = out[key][k]
    return t, cmd, out, filters


def find_jumps(t, out, cmd, thr):
    """Groups of consecutive steps where an output joint moves more than `thr`."""
    step = np.abs(np.diff(out, axis=0))                       # (n-1, 7)
    cstep = np.abs(np.diff(cmd, axis=0)).max(axis=1)
    hit = np.where(step.max(axis=1) > thr)[0] + 1             # step index k
    events = []
    for k in hit:
        if events and k == events[-1]["steps"][-1] + 1:
            events[-1]["steps"].append(k)
        else:
            events.append({"steps": [k]})
    for e in events:
        ks = e["steps"]
        k0 = ks[int(np.argmax([step[k - 1].max() for k in ks]))]
        delta = out[k0] - out[k0 - 1]
        big = np.where(np.abs(delta) > 0.25 * np.abs(delta).max())[0]
        e.update(step=k0, t=float(t[k0]), delta=delta, joints=[int(j) + 1 for j in big],
                 size=float(np.abs(delta).max()), speed=float(np.abs(delta).max() / DT),
                 ratio=float(np.abs(delta).max() / max(cstep[k0 - 1], 1e-12)),
                 cmd_step=float(cstep[k0 - 1]))
    return events


def wrist_gap_mm(sf, arm, cmd, out):
    """Per step: distance (mm) between the commanded wrist point and the output's."""
    other = sf.default_q["right" if arm == "left" else "left"]

    def wrist(q):
        kw = {"q_left": q, "q_right": other} if arm == "left" else {"q_right": q, "q_left": other}
        return np.asarray(sf.session.robot_fk_at(**kw)[arm]["W"])
    return np.array([1000.0 * np.linalg.norm(wrist(o) - wrist(c)) for c, o in zip(cmd, out)])


def report_jumps(label, events, thr, gap=None):
    if not events:
        print(f"  {label}: no step above {thr} rad -> no jump")
        return
    big = max(events, key=lambda e: e["size"])
    print(f"  {label}: {len(events)} jump event(s) above {thr} rad/step; "
          f"first at t = {events[0]['t']:.4f} s, largest at t = {big['t']:.4f} s")
    for tag, e in (("first", events[0]), ("largest", big)):
        if tag == "largest" and big is events[0]:
            continue
        d = ", ".join(f"j{j} {e['delta'][j - 1]:+.3f}" for j in e["joints"])
        print(f"      {tag:7s} step {e['step']} (t = {e['t']:.4f} s): joints {d} rad; "
              f"size {e['size']:.3f} rad in one {1000 * DT:.2f} ms step = {e['speed']:.0f} rad/s "
              f"(the command moved {e['cmd_step']:.4f} rad that step, so {e['ratio']:.0f}x more)")
        if gap is not None:
            print(f"              wrist gap: {gap[e['step'] - 1]:.1f} mm one step before, "
                  f"{gap[e['step']]:.1f} mm at the jump, {gap[min(e['step'] + 750, len(gap) - 1)]:.1f} mm 1 s later")


# ---------------------------------------------------------------- motion check
def motion_check(policy, cmd, out_on, stride=10):
    """Joint limits and self-collision of the commanded and the filtered motion.

    Collisions use MuJoCo contacts on Kong's bimanual model (collision geoms switched on
    in memory, mesh convex hulls), sampled every `stride` steps (75 Hz).
    """
    import mujoco
    import openarm_teleop
    from experiments.safety_filter_roundtrip import Arms

    spec = np.load(Path(openarm_teleop.__file__).parent / "assets/specs/openarm_v1.npz")
    lo, hi = spec[f"{policy.arm}_arm/joint_lower"], spec[f"{policy.arm}_arm/joint_upper"]
    arms = Arms()
    other = SOLVER_DEFAULT_Q
    print("\nMotion check (joint limits and self-collision):")
    print(f"  joint limits (rad), {policy.arm} arm: lower {lo}\n"
          f"                                      upper {hi}")
    ok = True
    for label, traj in (("commanded", cmd), ("filtered output (what the robot tracks)", out_on)):
        excess = np.maximum(np.maximum(lo - traj, traj - hi), 0).max(axis=0)
        kinds, same, finger, mind_aa, mind_at, n = {}, {}, 0.0, 9.9, 9.9, 0
        for q in traj[::stride]:
            ql, qr = (q, other) if policy.arm == "left" else (other, q)
            arms.set_q(ql, qr)
            for kind in arms.contacts():
                kinds[kind] = kinds.get(kind, 0) + 1
            mujoco.mj_collision(arms.m, arms.d)          # any contact within the same arm
            for i in range(arms.d.ncon):
                c = arms.d.contact[i]
                if c.dist < 0 and arms.owner[c.geom1] == arms.owner[c.geom2] != "torso":
                    pair = tuple(sorted((arms.m.body(arms.m.geom_bodyid[c.geom1]).name,
                                         arms.m.body(arms.m.geom_bodyid[c.geom2]).name)))
                    if all(name.endswith("_finger") for name in pair):
                        finger = min(finger, float(c.dist))   # the model's own finger overlap
                    else:
                        same[pair] = same.get(pair, 0) + 1
            caa, cat = arms.clearance()
            mind_aa, mind_at, n = min(mind_aa, caa), min(mind_at, cat), n + 1
        free = not kinds and not same
        ok &= bool(free and excess.max() <= 1e-6)
        print(f"  {label}: {n} poses checked; joint-limit excess max {excess.max():.1e} rad (tolerance 1e-6); "
              f"contacts: arm-arm/arm-torso {kinds or 'none'}, within one arm {same or 'none'}; "
              f"min mesh clearance arm-arm {1000 * mind_aa:.0f} mm, arm-torso {1000 * mind_at:.0f} mm")
        if finger < 0:
            print(f"      (not counted: the two gripper fingers overlap by {-1000 * finger:.1f} mm in "
                  f"every pose, a known issue in the model itself)")
    print(f"  -> {'OK: within limits and free of self-collision' if ok else 'PROBLEM: see above'}")
    return ok


# ---------------------------------------------------------------- outputs
def save_csv(path, t, cmd, out, events, gap):
    flags = {k: np.zeros(len(t), int) for k in out}
    for k, evs in events.items():
        for e in evs:
            flags[k][e["steps"]] = 1
    with open(path, "w", newline="") as fh:
        w = csv.writer(fh)
        w.writerow(["t"] + [f"cmd_j{i}" for i in range(1, 8)]
                   + [f"on_j{i}" for i in range(1, 8)] + [f"off_j{i}" for i in range(1, 8)]
                   + ["jump_on", "jump_off", "wrist_gap_on_mm"])
        for k in range(len(t)):
            w.writerow([f"{t[k]:.5f}"] + [f"{v:.6f}" for v in
                       (*cmd[k], *out["on"][k], *out["off"][k])]
                       + [flags["on"][k], flags["off"][k], f"{gap[k]:.3f}"])


def save_plot(path, t, cmd, out, events, policy, title, seed_mode):
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    INK, INK2, GRID = "#0b0b0b", "#52514e", "#e4e3df"
    BLUE, ORANGE, SURFACE = "#2a78d6", "#eb6834", "#fcfcfb"   # validated, CVD-safe pair
    fig, axes = plt.subplots(2, 1, figsize=(9.5, 6.4), sharex=True, facecolor=SURFACE)
    for ax, j in zip(axes, (3, 5)):
        ax.set_facecolor(SURFACE)
        ax.plot(t, cmd[:, j - 1], color="#8c8b86", lw=1.4, ls=":", label="commanded", zorder=2)
        ax.plot(t, out["off"][:, j - 1], color=ORANGE, lw=3.2, alpha=0.95,
                label="solver output, filter OFF (IK only)", zorder=3)
        ax.plot(t, out["on"][:, j - 1], color=BLUE, lw=1.4,
                label="solver output, filter ON (real case)", zorder=4)
        for key in ("off", "on"):
            for e in events[key]:
                ax.axvline(e["t"], color=INK2, lw=1.0, ls="--", zorder=1)
        ax.set_ylabel(f"joint {j} (rad)", color=INK)
        ax.grid(color=GRID, lw=0.8)
        ax.tick_params(colors=INK2)
        for side in ("top", "right"):
            ax.spines[side].set_visible(False)
        for side in ("left", "bottom"):
            ax.spines[side].set_color("#b9b8b2")
    first = min((e for ev in events.values() for e in ev), key=lambda e: e["t"], default=None)
    if first is not None:
        d = "; ".join(f"j{j} {first['delta'][j - 1]:+.2f} rad" for j in first["joints"])
        axes[0].annotate(f"branch jump at t = {first['t']:.2f} s\n{d}\n"
                         f"in one {1000 * DT:.2f} ms step ({first['speed']:.0f} rad/s)",
                         xy=(first["t"], out["off"][first["step"], 2] / 2 + 0.5),
                         xytext=(0.20, 0.50), textcoords="axes fraction", color=INK,
                         fontsize=9, va="center",
                         arrowprops=dict(arrowstyle="->", color=INK2, lw=1.0))
    axes[1].set_xlabel("time (s)", color=INK)
    axes[0].legend(loc="upper left", frameon=False, labelcolor=INK2, fontsize=9)
    fig.suptitle(title, color=INK, fontsize=11, x=0.01, ha="left")
    gap = float(np.abs(out["on"] - out["off"]).max())
    same = ("Filter ON and OFF overlap (max difference "
            f"{gap:.1e} rad): the jump is the IK, not the filter." if gap < 1e-3 else
            f"Filter ON and OFF differ by up to {gap:.2f} rad.")
    fig.text(0.01, 0.005, f"{policy.duration:g} s move then hold; 750 Hz; solver seeded with its "
             f"{'previous output' if seed_mode == 'previous' else 'command'}. "
             f"Dashed line = jump.\n{same}", color=INK2, fontsize=8)
    fig.tight_layout(rect=(0, 0.04, 1, 0.96))
    fig.savefig(path, dpi=150, facecolor=SURFACE)


# ---------------------------------------------------------------- physics model
# Bodies that get MuJoCo gravcomp = 1: both arms, joint 1 through the hand and fingers. link0 (the fixed
# arm mount) is left out. Applied by src/arm_actuators.py (robot_specs.ARM_ACTUATOR_SPECS["gravcomp_bodies"]).
GRAVCOMP_BODIES = [f"openarm_{side}_{name}" for side in ("left", "right")
                   for name in robot_specs.ARM_ACTUATOR_SPECS["gravcomp_bodies"]]


def load_model():
    """The chemistry-lab scene at the controller's 750 Hz timestep.

    Built through MjSpec with src/arm_actuators.py applied, as in RobotSimulator: the arm and finger
    position actuators (RobotController.step passes the targets straight through for them) and
    gravcomp = 1 on GRAVCOMP_BODIES (ngravcomp is fixed at compile time, so it cannot be set on a
    compiled model).
    """
    import mujoco
    from src.arm_actuators import add_arm_actuators
    scene = PROJECT_ROOT / "models" / "scenes" / "chemistry_lab_combined.xml"
    spec = mujoco.MjSpec.from_file(str(scene))
    add_arm_actuators(spec)
    m = spec.compile()
    m.opt.timestep = robot_specs.SIMULATION_TIMESTEP
    return m


# ---------------------------------------------------------------- hold check
def hold_check(policy, poses, settle=0.5, hold=2.0, verbose=True):
    """Hold poses with the PD (torque limits on, base stationary) and measure the hand's sag.

    poses: [(label, joints the PD tracks, commanded joints)]. The arm starts exactly at the
    tracked joints; after `settle` s (the base lands on its wheels, as in the video) the
    hand is measured for `hold` s. Sag = distance from the hand (tcp) to where the tracked
    joints put it kinematically, at the same base pose, so base motion does not count.
    Returns a list of dicts, one per pose. verbose=False prints nothing.
    """
    import mujoco
    from src.controller import RobotController
    log = print if verbose else (lambda *args, **kwargs: None)

    m = load_model()
    d, d2 = mujoco.MjData(m), mujoco.MjData(m)
    aid = lambda n: mujoco.mj_name2id(m, mujoco.mjtObj.mjOBJ_ACTUATOR, n)
    qadr = lambda a: m.jnt_qposadr[m.actuator_trnid[a, 0]]
    arm = policy.arm
    arm_ids = {s: [aid(f"{s}_joint{i}_ctrl") for i in range(1, 8)] for s in ("left", "right")}
    ctrl = RobotController(m)
    pd_mask = np.array(["_joint" in m.actuator(a).name or "_finger" in m.actuator(a).name
                        for a in range(m.nu)])
    lo, hi = m.actuator_forcerange[:, 0], m.actuator_forcerange[:, 1]
    limited = (hi > lo) & ~ctrl.is_position_actuator
    base_dof = m.jnt_dofadr[[j for j in range(m.njnt) if m.jnt_type[j] == 0][0]]
    tcp_id = m.body(f"openarm_{arm}_hand_tcp").id
    arm_lim = np.array([max(abs(lo[a]), abs(hi[a])) for a in arm_ids[arm]])
    log(f"\nHold check ({policy.arm} arm; PD at {RATE_HZ:g} Hz, torque limits on, "
          f"base velocity zeroed; {settle:g} s settle, then {hold:g} s measured):")
    gc = [m.body(i).name for i in range(m.nbody) if m.body_gravcomp[i] > 0]
    log(f"  gravcomp = 1 on {len(gc)} bodies (mass {sum(m.body_mass[m.body(n).id] for n in gc):.2f} kg): "
        f"{gc[0]} .. {gc[len(gc) // 2 - 1]} and {gc[len(gc) // 2]} .. {gc[-1]}; "
        f"all other bodies 0 (openarm_*_link0 and the base included)")
    results = []
    for label, q_pd, q_cmd in poses:
        mujoco.mj_resetData(m, d)
        d.qpos[0:3] = [-1.0, 3.5, 0.22]                         # controller's spawn pose
        for s in arm_ids:
            for a, v in zip(arm_ids[s], q_pd if s == arm else SOLVER_DEFAULT_Q):
                d.qpos[qadr(a)] = v
        mujoco.mj_forward(m, d)
        targets = np.zeros(m.nu)
        for s in arm_ids:
            targets[arm_ids[s]] = q_pd if s == arm else SOLVER_DEFAULT_Q
        for a in range(m.nu):
            if "_finger" in m.actuator(a).name:
                targets[a] = d.qpos[qadr(a)]

        def tcp_at(q):
            d2.qpos[:] = d.qpos
            for a, v in zip(arm_ids[arm], q):
                d2.qpos[qadr(a)] = v
            mujoco.mj_kinematics(m, d2)
            return d2.xpos[tcp_id].copy()

        sag, sag_z, torque, jerr = [], [], np.zeros(7), np.zeros(7)
        for k in range(int(round((settle + hold) * RATE_HZ))):
            pd = ctrl.step(targets, {"joint_angles": d.qpos, "joint_velocities": d.qvel})
            pd = np.where(limited, np.clip(pd, lo, hi), pd)
            d.ctrl[:] = np.where(pd_mask, pd, 0.0)
            d.qvel[base_dof:base_dof + 2] = 0.0
            d.qvel[base_dof + 3:base_dof + 6] = 0.0
            mujoco.mj_step(m, d)
            if k >= int(round(settle * RATE_HZ)):
                diff = d.xpos[tcp_id] - tcp_at(q_pd)
                sag.append(1000.0 * np.linalg.norm(diff))
                sag_z.append(1000.0 * diff[2])
                torque = np.maximum(torque, np.abs(d.ctrl[arm_ids[arm]]) / arm_lim)
                jerr = np.maximum(jerr, np.abs(d.qpos[[qadr(a) for a in arm_ids[arm]]] - q_pd))
        moved = 1000.0 * float(np.linalg.norm(tcp_at(q_pd) - tcp_at(q_cmd)))
        r = dict(label=label, final_mm=sag[-1], max_mm=max(sag), final_z_mm=sag_z[-1],
                 torque_frac=float(torque.max()), torque_joint=int(torque.argmax()) + 1,
                 joint_err=float(jerr.max()), joint_err_j=int(jerr.argmax()) + 1, cmd_gap_mm=moved)
        results.append(r)
        log(f"  {label}: hand sag {r['final_mm']:.2f} mm after {hold:g} s (peak {r['max_mm']:.2f} mm; "
              f"vertical {r['final_z_mm']:+.2f} mm); worst joint error {r['joint_err']:.4f} rad "
              f"(j{r['joint_err_j']}); highest torque {100 * r['torque_frac']:.0f}% of the limit "
              f"(j{r['torque_joint']}); filter output vs command at this pose: {moved:.1f} mm apart")
    return results


# ---------------------------------------------------------------- video
def render_video(path, t, cmd, out_on, policy, events, rich=False, still_dir=None,
                 slowmo=0.25, slow_window=0.5, fps=30, still_prefix="reach"):
    """Physics with the PD tracking the filtered output; render the arm offscreen.

    rich=False: the plain 640x480 video (failure scenario). rich=True: a 1280x720 side
    view with markers on the hand (orange = commanded, blue = actual), a legend, time /
    commanded elbow / gap text, a SNAP label, slow motion (`slowmo` x for +-`slow_window`
    s around the first snap) and, if `still_dir` is given, stills just before and just
    after the snap. Returns a dict of facts measured in the physics run.

    Gravity compensation is on every arm link (src/arm_actuators.py), so gravity is cancelled
    outside the motors. Why: with torque limits on, the 7 N m wrist motors cannot hold this
    wrist posture at full reach, so without it the hand droops ~0.1-0.2 m before the snap and
    hides it.
    """
    import cv2
    import mujoco
    from src.controller import RobotController

    m = load_model()
    w, h = (1280, 720) if rich else (640, 480)
    m.vis.global_.offwidth = max(m.vis.global_.offwidth, w)
    m.vis.global_.offheight = max(m.vis.global_.offheight, h)
    d = mujoco.MjData(m)
    d.qpos[0:3] = [-1.0, 3.5, 0.22]                            # controller's spawn pose
    aid = lambda n: mujoco.mj_name2id(m, mujoco.mjtObj.mjOBJ_ACTUATOR, n)
    qadr = lambda a: m.jnt_qposadr[m.actuator_trnid[a, 0]]
    arm = policy.arm
    arm_ids = {s: [aid(f"{s}_joint{i}_ctrl") for i in range(1, 8)] for s in ("left", "right")}
    for s in arm_ids:
        start = policy.start if s == arm else SOLVER_DEFAULT_Q
        for a, v in zip(arm_ids[s], start):
            d.qpos[qadr(a)] = v
    mujoco.mj_forward(m, d)
    ctrl = RobotController(m)
    pd_mask = np.array(["_joint" in m.actuator(a).name or "_finger" in m.actuator(a).name
                        for a in range(m.nu)])
    lo, hi = m.actuator_forcerange[:, 0], m.actuator_forcerange[:, 1]
    limited = (hi > lo) & ~ctrl.is_position_actuator
    base_dof = m.jnt_dofadr[[j for j in range(m.njnt) if m.jnt_type[j] == 0][0]]
    targets = np.zeros(m.nu)
    for s in arm_ids:
        targets[arm_ids[s]] = policy.start if s == arm else SOLVER_DEFAULT_Q
    for a in range(m.nu):                                       # fingers hold where they are
        if "_finger" in m.actuator(a).name:
            targets[a] = d.qpos[qadr(a)]
    robot_bodies = {b for b in range(m.nbody) if m.body(b).name.startswith("openarm_")}
    contacts_seen = {}

    def step(tgt):
        pd = ctrl.step(tgt, {"joint_angles": d.qpos, "joint_velocities": d.qvel})
        pd = np.where(limited, np.clip(pd, lo, hi), pd)         # motor torque limits
        d.ctrl[:] = np.where(pd_mask, pd, 0.0)
        d.qvel[base_dof:base_dof + 2] = 0.0                      # base stays put
        d.qvel[base_dof + 3:base_dof + 6] = 0.0
        mujoco.mj_step(m, d)

    def note_contacts():                                        # robot body vs robot body
        for i in range(d.ncon):
            c = d.contact[i]
            b1, b2 = m.geom_bodyid[c.geom1], m.geom_bodyid[c.geom2]
            if b1 in robot_bodies and b2 in robot_bodies and c.dist < 0:
                key = tuple(sorted((m.body(b1).name, m.body(b2).name)))
                contacts_seen[key] = min(contacts_seen.get(key, 0.0), float(c.dist))

    for _ in range(int(0.5 * RATE_HZ)):                         # settle at the start pose
        step(targets)

    side_sign = 1.0 if arm == "left" else -1.0
    base_id = m.body("openarm_body_link0").id
    tcp_id = m.body(f"openarm_{arm}_hand_tcp").id
    renderer = mujoco.Renderer(m, height=h, width=w)
    renderer.scene.flags[mujoco.mjtRndFlag.mjRND_SHADOW] = 0
    renderer.scene.flags[mujoco.mjtRndFlag.mjRND_REFLECTION] = 0
    cam = mujoco.MjvCamera()
    if rich:       # side view: camera on the arm's own side looking across, arm in profile
        cam.distance, cam.elevation = 1.45, -2
        cam.azimuth = 270.0 if arm == "left" else 90.0
    else:
        cam.distance, cam.elevation = 1.5, -12
        cam.azimuth = 220.0 if arm == "left" else 140.0
    writer = cv2.VideoWriter(str(path), cv2.VideoWriter_fourcc(*"mp4v"), fps, (w, h))
    snap_t = events[0]["t"] if events else None
    d2 = mujoco.MjData(m)                                       # scratch: pose of the command

    def commanded_tcp(idx):
        d2.qpos[:] = d.qpos
        for a, v in zip(arm_ids[arm], cmd[idx]):
            d2.qpos[qadr(a)] = v
        mujoco.mj_kinematics(m, d2)
        return d2.xpos[tcp_id].copy()

    ORANGE, BLUE = (52, 104, 235), (214, 120, 42)               # BGR of #eb6834 / #2a78d6
    want = {"before": None if snap_t is None else snap_t - 0.05,
            "after": None if snap_t is None else snap_t + 0.35}
    best = {k: (9.9, None) for k in want}
    info = dict(gap_max_mm=0.0, gap_after_mm=None, gap_before_mm=None, frames=0, slow_frames=0)
    sim_t, idx, frame_i = 0.0, 0, 0
    n = len(t)
    while idx < n - 1 or frame_i == 0:
        slow = rich and snap_t is not None and abs(sim_t - snap_t) <= slow_window
        sim_t += (slowmo if slow else 1.0) / fps
        target_idx = min(n - 1, int(round(sim_t * RATE_HZ)))
        while idx < target_idx:
            idx += 1
            targets[arm_ids[arm]] = out_on[idx]
            step(targets)
            if idx % 5 == 0:
                note_contacts()
        if rich:
            cam.lookat[:] = d.xpos[base_id] + np.array([0.28, side_sign * 0.15, 0.78])
        else:
            cam.lookat[:] = d.xpos[base_id] + np.array([0.3, side_sign * 0.15, 0.4])
        renderer.update_scene(d, camera=cam)
        actual, wanted = d.xpos[tcp_id].copy(), commanded_tcp(idx)
        gap = 1000.0 * float(np.linalg.norm(actual - wanted))
        info["gap_max_mm"] = max(info["gap_max_mm"], gap)
        if rich:
            scn = renderer.scene
            for pos, r, rgba in ((wanted, 0.032, (0.92, 0.41, 0.20, 0.55)),
                                 (actual, 0.019, (0.16, 0.47, 0.84, 1.0))):
                g = scn.geoms[scn.ngeom]
                mujoco.mjv_initGeom(g, mujoco.mjtGeom.mjGEOM_SPHERE, np.array([r, 0, 0]),
                                    pos, np.eye(3).ravel(), np.array(rgba, dtype=np.float32))
                scn.ngeom += 1
            if gap > 8.0:                                       # thin line between the two
                g = scn.geoms[scn.ngeom]
                mujoco.mjv_initGeom(g, mujoco.mjtGeom.mjGEOM_CAPSULE, np.zeros(3), np.zeros(3),
                                    np.eye(3).ravel(), np.array([0.1, 0.1, 0.1, 1.0], dtype=np.float32))
                mujoco.mjv_connector(g, mujoco.mjtGeom.mjGEOM_CAPSULE, 0.004, wanted, actual)
                scn.ngeom += 1
        img = cv2.cvtColor(renderer.render(), cv2.COLOR_RGB2BGR)
        font, sc, th = cv2.FONT_HERSHEY_SIMPLEX, (0.8 if rich else 0.55), (2 if rich else 1)
        if rich:
            lines = [f"t = {sim_t:5.2f} s",
                     f"commanded elbow (joint 4) = {np.degrees(cmd[idx, 3]):5.1f} deg",
                     f"hand gap, commanded vs actual = {gap:4.0f} mm",
                     f"{arm} arm, safety filter ON, PD tracks the filter output"]
            cv2.rectangle(img, (0, 0), (760, 8 + 34 * len(lines)), (35, 35, 35), -1)
            for i, line in enumerate(lines):
                cv2.putText(img, line, (14, 32 + 34 * i), font, sc, (255, 255, 255), th, cv2.LINE_AA)
            # legend (bottom left)
            cv2.rectangle(img, (0, h - 98), (470, h), (35, 35, 35), -1)
            for i, (col, txt) in enumerate(((ORANGE, "commanded hand position"),
                                            (BLUE, "actual hand position"))):
                cv2.circle(img, (30, h - 66 + 42 * i), 13, col, -1, cv2.LINE_AA)
                cv2.putText(img, txt, (58, h - 56 + 42 * i), font, 0.75, (255, 255, 255), 2, cv2.LINE_AA)
            if snap_t is not None and 0.0 <= sim_t - snap_t <= 0.8:
                cv2.rectangle(img, (w - 270, 0), (w, 78), (40, 40, 200), -1)
                cv2.putText(img, "SNAP", (w - 245, 56), font, 1.8, (255, 255, 255), 4, cv2.LINE_AA)
            if slow:
                cv2.rectangle(img, (w // 2 - 190, h - 62), (w // 2 + 190, h - 12), (20, 140, 230), -1)
                cv2.putText(img, f"SLOW MOTION {slowmo:g}x", (w // 2 - 170, h - 26), font, 0.95,
                            (255, 255, 255), 2, cv2.LINE_AA)
        else:
            q = np.array([d.qpos[qadr(a)] for a in arm_ids[arm]])
            lines = [f"t = {sim_t:.2f} s   {arm} arm   filtered output tracked by PD",
                     f"joint 3: output {out_on[idx, 2]:+.2f}  actual {q[2]:+.2f} rad",
                     f"joint 5: output {out_on[idx, 4]:+.2f}  actual {q[4]:+.2f} rad"]
            cv2.rectangle(img, (0, 0), (430, 74), (35, 35, 35), -1)
            for i, line in enumerate(lines):
                cv2.putText(img, line, (10, 22 + 22 * i), font, sc, (255, 255, 255), th, cv2.LINE_AA)
            if snap_t is not None and 0.0 <= sim_t - snap_t <= 0.4:
                cv2.rectangle(img, (10, h - 44), (250, h - 12), (40, 40, 200), -1)
                cv2.putText(img, "BRANCH JUMP", (20, h - 21), font, 0.7, (255, 255, 255), 2, cv2.LINE_AA)
        writer.write(img)
        for k, tk in want.items():
            if tk is not None and abs(sim_t - tk) < best[k][0]:
                best[k] = (abs(sim_t - tk), img.copy())
                info["gap_after_mm" if k == "after" else "gap_before_mm"] = gap
        info["frames"] += 1
        info["slow_frames"] += int(slow)
        frame_i += 1
    writer.release()
    if still_dir is not None:
        for k, (_, im) in best.items():
            if im is not None:
                cv2.imwrite(str(Path(still_dir) / f"{still_prefix}_{k}.png"), im)
    info["contacts"] = contacts_seen
    info["duration_s"] = info["frames"] / fps
    return info


# ---------------------------------------------------------------- main
def main():
    ap = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    ap.add_argument("--scenario", choices=("failure", "reach"), default="failure",
                    help="failure: drive toward a config that fails to round-trip; "
                         "reach: natural pose -> full forward reach at shoulder height")
    ap.add_argument("--arm", choices=("left", "right"), default="left", help="reach scenario arm")
    ap.add_argument("--index", type=int, default=0,
                    help="failure scenario: which failing config (0 = the biggest jump)")
    ap.add_argument("--seed", type=int, default=0, help="sampling seed of safety_filter_roundtrip")
    ap.add_argument("--duration", type=float, default=None,
                    help="seconds to reach the target (failure 5, reach 4)")
    ap.add_argument("--hold", type=float, default=None,
                    help="seconds to hold at the target (failure 1, reach 2)")
    ap.add_argument("--profile", choices=("linear", "smooth"), default=None,
                    help="time profile (failure linear, reach smooth)")
    ap.add_argument("--seed-mode", choices=("previous", "command"), default="previous",
                    help="seed the solver with its previous output or with the command")
    ap.add_argument("--jump-threshold", type=float, default=0.1,
                    help="rad of output change in one 750 Hz step that counts as a jump")
    ap.add_argument("--check-sag", action="store_true",
                    help="reach scenario: only run the 2 s hold check (start and extended pose) and exit")
    ap.add_argument("--sag-limit-mm", type=float, default=5.0,
                    help="reach video: do not render if the hold check sags more than this")
    ap.add_argument("--slowmo", type=float, default=0.25, help="reach video: slow-motion speed")
    ap.add_argument("--slow-window", type=float, default=0.5,
                    help="reach video: seconds of slow motion on either side of the snap")
    ap.add_argument("--out", default="data/branch_jump")
    ap.add_argument("--list", action="store_true", help="list the failing configs and exit")
    ap.add_argument("--video", action="store_true", help="also render an MP4 (EGL, offscreen)")
    args = ap.parse_args()
    reach = args.scenario == "reach"
    duration = args.duration if args.duration is not None else (4.0 if reach else 5.0)
    hold = args.hold if args.hold is not None else (2.0 if reach else 1.0)
    profile = args.profile or ("smooth" if reach else "linear")

    if reach:
        policy = BranchJumpPolicy.reach_forward(args.arm, duration=duration, profile=profile)
        title = (f"Solver snap while reaching forward at shoulder height ({policy.arm} arm): "
                 f"elbow 90 deg -> straight, {profile} motion")
        print(f"\nReach forward ({policy.arm} arm): joints at the start {policy.start}\n"
              f"                              joints at full reach {policy.target}")
        prefix = "reach_"
    else:
        policy, failure, failures = BranchJumpPolicy.from_failure(
            args.index, seed=args.seed, duration=duration)
        print(f"\nConfigs that failed to round-trip with the filter OFF "
              f"(safety_filter_roundtrip.py --spread 0 --seed {args.seed}), biggest first:")
        print("  idx arm    max err   worst joints (err rad)            source")
        for i, f in enumerate(failures):
            top = np.argsort(-f["joints"])[:2]
            print(f"  {i:3d} {f['arm']:5s} {f['error']:8.3f}   "
                  + ", ".join(f"j{j + 1} {f['joints'][j]:.2f}" for j in top).ljust(34)
                  + f"{f['source']} #{f['index']}" + ("   <-- chosen" if i == args.index else ""))
        if args.list:
            return
        print(f"\nTarget ({policy.arm} arm): {failure['q']}")
        print(f"Solver returns for it (filter off): {failure['out']}")
        title = (f"Solver branch jump: {policy.arm} arm, straight joint-space line to a "
                 f"failing config (index {failure['index']}, {failure['source']})")
        prefix = ""
    policy.profile = profile

    t, cmd, out, filters = run_trajectory(policy, args.seed_mode, hold)
    print(f"\nStepped {len(t)} steps at {RATE_HZ:g} Hz ({t[-1]:.2f} s sim time); the command "
          f"moves at most {np.abs(np.diff(cmd, axis=0)).max():.4f} rad per step. "
          f"Solver seeded with its {'previous output' if args.seed_mode == 'previous' else 'command'}.")
    if reach:
        print(f"Commanded elbow (joint 4): {np.degrees(cmd[0, 3]):.0f} deg at the start -> "
              f"{np.degrees(cmd[-1, 3]):.1f} deg at the end")
        motion_check(policy, cmd, out["on"])
    events = {k: find_jumps(t, out[k], cmd, args.jump_threshold) for k in out}
    gap = wrist_gap_mm(filters["on"], policy.arm, cmd, out["on"])
    print(f"\nJump detection (an output joint moving more than {args.jump_threshold} rad in one step):")
    report_jumps("filter OFF (IK only)", events["off"], args.jump_threshold)
    report_jumps("filter ON  (real case)", events["on"], args.jump_threshold, gap)
    err = {k: np.abs(out[k][-1] - cmd[-1]) for k in out}
    print(f"\nAt the end (t = {t[-1]:.2f} s) the output differs from the command by up to "
          f"{err['off'].max():.3f} rad (filter OFF) / {err['on'].max():.3f} rad (filter ON); "
          f"joints with error > 0.05 rad (OFF): {[int(j) + 1 for j in np.where(err['off'] > 0.05)[0]]}")
    print(f"Wrist gap (filter ON): max {gap.max():.1f} mm at t = {t[int(gap.argmax())]:.3f} s; "
          f"at the end {gap[-1]:.1f} mm")
    if reach and events["on"]:
        e = events["on"][0]
        print(f"\nSNAP (filter ON): t = {e['t']:.4f} s, commanded elbow {np.degrees(cmd[e['step'], 3]):.2f} deg "
              f"({cmd[e['step'], 3]:.4f} rad), joint jumps "
              + ", ".join(f"j{j} {e['delta'][j - 1]:+.3f} rad" for j in range(1, 8)
                          if abs(e['delta'][j - 1]) > 0.005)
              + f"; wrist gap {gap[e['step']]:.1f} mm right after (step {e['step']})")

    out_dir = PROJECT_ROOT / args.out
    out_dir.mkdir(parents=True, exist_ok=True)
    save_csv(out_dir / f"{prefix}trajectory.csv", t, cmd, out, events, gap)
    save_plot(out_dir / f"{prefix}trajectory.png", t, cmd, out, events, policy, title, args.seed_mode)
    print(f"\nSaved {out_dir / (prefix + 'trajectory.csv')}\nSaved {out_dir / (prefix + 'trajectory.png')}")
    if reach and (args.video or args.check_sag):
        sag = hold_check(policy, [("start pose", out["on"][0], cmd[0]),
                                  ("fully extended pose", out["on"][-1], cmd[-1])])
        worst = max(r["final_mm"] for r in sag)
        if worst > args.sag_limit_mm:
            print(f"\nSTOP: the hand sags {worst:.1f} mm (limit {args.sag_limit_mm:g} mm); nothing rendered.")
            sys.exit(2)
        print(f"  -> sag within {args.sag_limit_mm:g} mm")
    if args.check_sag:
        return
    if args.video:
        mp4 = out_dir / ("reach_forward.mp4" if reach else "branch_jump.mp4")
        video_events = events["on"] if reach else events["off"] + events["on"]
        info = render_video(mp4, t, cmd, out["on"], policy, video_events, rich=reach,
                            still_dir=out_dir if reach else None,
                            slowmo=args.slowmo, slow_window=args.slow_window)
        print(f"Saved {mp4}")
        if reach:
            print(f"  video: {info['frames']} frames, {info['duration_s']:.1f} s at 30 fps "
                  f"({info['slow_frames']} slow-motion frames); hand gap (commanded vs actual): "
                  f"{info['gap_before_mm']:.0f} mm in the 'before' still, {info['gap_after_mm']:.0f} mm in the "
                  f"'after' still, max {info['gap_max_mm']:.0f} mm\n"
                  f"  stills: {out_dir / 'reach_before.png'}, {out_dir / 'reach_after.png'}\n"
                  f"  physics contacts between robot bodies during the motion: "
                  f"{info['contacts'] or 'none'}")


if __name__ == "__main__":
    main()
